/**
 * One evidence record of a tracked application.
 *
 * The evidence rows are not part of the tracking API's schema (they are
 * read through the artifact endpoint), so this shape is written here, next
 * to the generated ones, with the reason.
 */
export interface ApplicationEvidenceRecord {
  confirmation_text: string | null
  status: string
  screenshot_path: string | null
  trace_path: string | null
  job_url: string
  recorded_at: string | null
}
export type WorkPreferences = DeepRequired<
  components["schemas"]["WorkPreferences"]
>

/**
 * One document the account already has.
 *
 * The library is the union of the uploaded résumés (a résumé *is* a
 * candidate profile in this system) and the tailored résumés the agent
 * produced. The shape is written here because the route has no response
 * model to generate it from.
 */
export interface DocumentRecord {
  id: string
  kind: "resume" | "tailored"
  title: string
  filename: string
  path: string
  size_bytes: number | null
  created_at: string | null
  profile_id: string | null
  job_id: string | null
}

/**
 * One audit row (WS-14 · Phase C).
 *
 * `GET /api/audit` declares no response model, so this shape is written
 * here, next to the generated ones, with the reason. It mirrors the dict
 * the route assembles from `AuditEventDB`.
 */
export interface AuditEvent {
  id: number
  recorded_at: string | null
  action: string
  actor: string
  /** `user` | `agent` | `system`. */
  actor_kind: string
  actor_id: string | null
  resource: string
  /** `success` | `blocked` | `denied` | `error`. */
  outcome: string
  workflow_id: string | null
  metadata: Record<string, unknown>
}

export interface AuditPage {
  events: AuditEvent[]
  count: number
}

/**
 * The platform overview (WS-14 · the administrator surface).
 *
 * Written here for the same reason as `AuditEvent`: the route is new and
 * deliberately carries no generated response model yet.
 */
export interface AdminOverview {
  accounts: { total: number; active: number; superusers: number }
  applications: { total: number; by_status: Record<string, number> }
  workflows: { total: number }
  audit: {
    total: number
    by_outcome: Record<string, number>
    by_actor_kind: Record<string, number>
  }
  corpus: { jobs: number }
  generated_at: string
}

/**
 * Durable background execution (WS-18).
 *
 * These shapes are written here because the routes declare `dict` bodies
 * (the run payload is assembled by `src.runs.service.run_to_dict`), so there
 * is no generated schema to alias. They mirror that function exactly.
 */
export interface RunAccepted {
  run_id: string
  status: string
  job_type: string
  correlation_id: string
  created_at: string
  existing: boolean
}

export interface RunLease {
  owner: string | null
  expires_at: string | null
}

export interface RunSummary {
  id: string
  job_type: string
  status: string
  priority: number
  owner_id: string | null
  correlation_id: string
  parent_run_id: string | null
  embedding_model: string | null
  embedding_dimension: number | null
  created_at: string | null
  started_at: string | null
  completed_at: string | null
  heartbeat_at: string | null
  lease: RunLease
  attempt_count: number
  total_items: number
  completed_items: number
  failed_items: number
  skipped_items: number
  remaining_items: number
  progress_percent: number
  last_error: string | null
  last_error_kind: string | null
  metadata: Record<string, unknown>
  resumable: boolean
  cancellable: boolean
}

export interface RunEvent {
  id: number
  event: string
  at: string | null
  actor: string
  actor_kind: string
  message: string | null
  metadata: Record<string, unknown>
}

export interface FailedWorkItem {
  id: string
  job_id: string
  attempt_count: number
  last_error: string | null
  last_error_kind: string | null
}

export interface RunDetail extends RunSummary {
  items: {
    queued: number
    running: number
    retry_wait: number
    completed: number
    failed: number
    cancelled: number
  }
  events: RunEvent[]
  failed_work_items?: FailedWorkItem[]
  checkpoint: {
    last_event: RunEvent | null
    heartbeat_at: string | null
  }
}

export interface RunsListResponse {
  runs: RunSummary[]
  count: number
}

export interface RunDetailResponse {
  run: RunDetail
}

export interface RunActionResponse {
  run_id: string
  status: string
  job_type: string
  queued: boolean
}

export interface WorkerHealthEntry {
  worker_id: string
  status: string
  hostname: string
  pid: number | null
  heartbeat_age_seconds: number
  healthy: boolean
  starts: number
  processed_items: number
  failed_items: number
  work_per_minute: number
  current_run_id: string | null
}

export interface WorkerHealth {
  healthy: number
  total: number
  stale_after_seconds: number
  workers: WorkerHealthEntry[]
}

export interface WorkerHealthResponse {
  workers: WorkerHealth
  queue: QueueStats
}

export interface QueueStats {
  items: {
    queued: number
    running: number
    retry_wait: number
    completed: number
    failed: number
    cancelled: number
    stale_leases: number
    reclaimed_leases: number
    oldest_pending_age_seconds: number
  }
  runs: Record<string, number>
}

export interface AdminJobMetrics {
  queue: QueueStats
  workers: WorkerHealth
  breakers: {
    name: string
    state: string
    failure_count: number
    retry_after_seconds: number | null
  }[]
  embedding: {
    corpus: number
    budget: {
      documents_today: number
      documents_limit: number
      requests_today: number
      requests_limit: number
      cache_entries: number
      cache_limit: number
    }
    runs: { active: number; recoverable: number }
  }
  generated_at: string
}
